/** Every art id, in manifest order. */
export const ART_IDS = Object.keys(ART) as ArtId[];

export function isArtId(id: string): id is ArtId {
  return Object.hasOwn(ART, id);
}

/** The manifest entry for an id. Ids are a closed union, so a typo is a type error. */
export function art(id: ArtId): ArtAsset {
  return ART[id];
}

/** Track (tier) id to its emblem. */
export const TRACK_ART = {
  cumulus: 'track-cumulus',
  nimbus: 'track-nimbus',
  stratus: 'track-stratus',
} as const satisfies Record<string, ArtId>;

/**
 * The plate for a curriculum module, by the module label used in `shared/curriculum.ts` ("The network",
 * "Containers", "Deploy", ...). Case and a leading "The" are ignored. Undefined for unknown modules.
 */
export function moduleArt(label: string): ArtId | undefined {
  const lower = label.trim().toLowerCase();
  const id = `mod-${lower.replace(/^the\s+/, '')}`;
  return isArtId(id) ? id : undefined;
}

/** The emblem for a lab id (`LABS` in shared/curriculum.ts). Undefined for unknown labs. */
export function labArt(labId: string): ArtId | undefined {
  const id = `lab-${labId}`;
  return isArtId(id) ? id : undefined;
}

/** The medal for an achievement id (CONTENT.md section 6). Undefined for unknown achievements. */
export function medalArt(achievementId: string): ArtId | undefined {
  const id = `medal-${achievementId}`;
  return isArtId(id) ? id : undefined;
}
